import numpy as np
L=[l.split() for l in open('opt4.xyz').read().split('\n')[2:] if l.strip()]
P=np.array([[float(x) for x in l[1:]] for l in L]); S=[l[0] for l in L]
from collections import Counter
print(Counter(S), len(S))
cov={'H':0.31,'C':0.76,'N':0.71,'O':0.66,'Cl':1.02,'Rh':1.42}
D=np.linalg.norm(P[:,None]-P[None],axis=2)
nb={i:[] for i in range(len(S))}
for i in range(len(S)):
    for j in range(i+1,len(S)):
        if D[i,j] < 1.3*(cov[S[i]]+cov[S[j]]):
            nb[i].append(j); nb[j].append(i)
for i in range(len(S)):
    print(i,S[i],[(j,S[j]) for j in nb[i]])
EOF
